window.kbPageData["views/entry/k-67007d1bb4a28f68"] = {"key":"entry/k-67007d1bb4a28f68","state":{"route":"entry/k-67007d1bb4a28f68"},"node":{"id":"k-67007d1bb4a28f68","mode":"k","title":"维护国家利益、公共利益受伤视同工伤","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["在维护国家利益或公共利益的活动中受伤视同工伤"],"qs":["江苏 2024 A类 行测#8"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"引用网址未能与本次实际检索资料逐项对应，需核查原出处。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：李某的救助属于维护公共利益，其受伤应视同工伤","review":{"definition":"原题引文：李某的救助属于维护公共利益，其受伤应视同工伤","explanation":"最高人民法院指导案例94号确认，职工为制止违法犯罪行为受伤可以适用该条。南阳市中级人民法院也曾认定，下班后舍身救助一名溺水同事的职工应视同工伤，可见救助对象只有一人也可能符合条件。本题D项直接把李某值班时赶去救助翻车的王某定性为维护公共利益，参考答案排除D。能否适用该条仍须结合施救活动的性质及有关认定判断。","references":[{"source":"web-c6bb16c71c2c403b","location":"裁判要点","quote":"为制止违法犯罪行为而受到伤害的"},{"source":"web-78cfa73a3e610d5b","location":"正文首段，南阳市中级人民法院网站转载","quote":"认定李东应视同工伤"}],"evidence":"李某的救助属于维护公共利益，其受伤应视同工伤","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 A类 行测#8":{"paper":"江苏 2024 A类 行测","n":8,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",3],"card":"eb776cae7db026319d933503","links":[{"id":"k-67007d1bb4a28f68","role":"解题依据","why":"适用这一视同工伤条款须判断受伤所涉活动是否具有法定的公共利益性质。"}]}},"terms":{},"references":{"web-c6bb16c71c2c403b":{"name":"最高人民法院指导案例94号","url":"https://www.court.gov.cn/fabu/xiangqing/104272.html"},"web-78cfa73a3e610d5b":{"name":"《人民法院报》：南阳判定见义勇为遇难职工属工伤","url":"https://nyzy.hncourt.gov.cn/public/detail.php?id=7146"}},"topics":[],"units":{"k-67007d1bb4a28f68":[["江苏 2024 A类 行测#8"]]}};
